def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    bits = int(state, 2)
    mask = (1 << n) - 1
    shifts = [offset % n for offset in offsets]

    while t:
        if t & 1:
            result = 0
            for shift in shifts:
                result ^= ((bits << shift) | (bits >> (n - shift))) & mask
            bits = result

        t >>= 1
        shifts = [(shift * 2) % n for shift in shifts]

    return format(bits, f"0{n}b")
